const sectionRevision = "edd1c9963412";

// Shared by the published finder and regression checks. No network or browser state.
const normalizeTaskQuery = value => String(value||'').toLowerCase().normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '').replace(/blood\s+hound|bloodhond/g, 'bloodhound')
  .replace(/neo\s+4j/g, 'neo4j').replace(/kerberosting/g,'kerberoasting').replace(/dc\s+sync/g,'dcsync')
  .replace(/[^a-z0-9]+/g, ' ').trim();
const taskQueryTerms = query => {
  const stop=new Set(['how','do','i','a','an','the','to','my','can','with','in','on','for','is','of','where','find','please','me']);
  return [...new Set(normalizeTaskQuery(query).split(' ').filter(t=>t&&!stop.has(t)))];
};
const findVaultTasks = (entries, query, category = 'All topics', kind='All types') => {
  const clean=normalizeTaskQuery(query),terms=taskQueryTerms(query);
  const matched=entries.filter(e=>(category==='All topics'||e.category===category)&&(kind==='All types'||e.kind===kind)).map(entry=>{
    const title=normalizeTaskQuery(entry.title),keys=normalizeTaskQuery((entry.keywords||[]).join(' ')),description=normalizeTaskQuery(entry.description),trail=normalizeTaskQuery(entry.trail);
    const body=entry.terms||'',heading=title+' '+keys+' '+description+' '+trail;
    const inBody=term=>(' '+body+' ').includes(' '+term+' ');
    if(terms.some(term=>!heading.includes(term)&&!inBody(term)))return {entry,score:-1};
    let score=terms.length?terms.reduce((sum,term)=>sum+(title.includes(term)?12:keys.includes(term)?6:trail.includes(term)?3:1),0)+(clean&&title.includes(clean)?30:0)+(entry.kind==='Task'?8:0):entry.featured?100-entry.featured:entry.kind==='Task'?10:0;
    if(terms.length&&entry.kind==='Command'&&[entry.title,...entry.keywords].some(a=>normalizeTaskQuery(a)===clean))score+=200;
    if(terms.length&&entry.kind==='Section')score+=-5+6/(1+body.split(' ').length/80);
    if(terms.length&&entry.kind==='Box'&&terms.some(t=>title.split(' ').includes(t)&&!['htb','practice'].includes(t)))score+=15;
    if(entry.legacy&&!/legacy|historical/.test(clean))score-=15;
    // Match body text too, while keeping hand-reviewed task shortcuts easy to spot.
    return {entry,score:Math.max(0,score)};
  }).filter(x=>x.score>=0).sort((a,b)=>b.score-a.score||a.entry.title.localeCompare(b.entry.title));
  const seen=new Set();return matched.filter(({entry})=>{if(seen.has(entry.href))return false;seen.add(entry.href);return true;}).map(x=>x.entry);
};

